// downInstances lists the instances whose up sample is 0, with the time and
// a random nonce the runner fixes, so every host gives the same labels.
// Protobuf JSON omits a zero value, so a missing value is 0.
interface Label {
  name?: string
  value?: string
}

interface QueryResponse {
  series?: { labels?: { labels?: Label[] }; samples?: { value?: number }[] }[]
}

export default function downInstances(input: QueryResponse) {
  const down = (input.series ?? [])
    .filter((s) => ((s.samples ?? []).at(-1)?.value ?? 0) === 0)
    .map((s) => s.labels?.labels?.find((l) => l.name === 'instance')?.value ?? '')
    .sort()
  return {
    labels: [
      { name: 'checked_at', value: new Date().toISOString() },
      { name: 'down', value: down.join(',') },
      { name: 'nonce', value: Math.random().toFixed(9) },
    ],
  }
}

